package main

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const knowledgeBootstrapLimit = 24 * 1024

func knowledgeMarkdownBody(raw []byte) []byte {
 s:=string(raw)
 if !strings.HasPrefix(s,"---\n"){return raw}
 if end:=strings.Index(s[4:],"\n---\n");end>=0{return []byte(s[4+end+5:])}
 return raw
}


// KnowledgeContextRequest is generated by agent assignment and project/task metadata.
// IDs are stable across revisions. The source manifest owns role/language applicability.
type KnowledgeContextRequest struct {
	AgentID string `json:"agentId"`
	Root string `json:"root"`
	Role string `json:"role"`
	Languages []string `json:"languages"`
	Assigned []string `json:"assigned"`
	Task string `json:"task"`
}

type KnowledgeTraceEvent struct {
 RunID string `json:"runId,omitempty"`
 AgentID string `json:"agentId,omitempty"`
 At string `json:"at,omitempty"`
 InputTokens int64 `json:"inputTokens,omitempty"`
 OutputTokens int64 `json:"outputTokens,omitempty"`
 CacheReadTokens int64 `json:"cacheReadTokens,omitempty"`
 CacheWriteTokens int64 `json:"cacheWriteTokens,omitempty"`
	Kind string `json:"kind"`
	DocumentID string `json:"documentId,omitempty"`
	Status string `json:"status,omitempty"`
	Reason string `json:"reason,omitempty"`
	SHA256 string `json:"sha256,omitempty"`
	EstimatedTokens int64 `json:"estimatedTokens,omitempty"`
}
type KnowledgeContext struct {
	Bootstrap string `json:"bootstrap"`
	Index string `json:"index"`
	Directory string `json:"directory"`
	EstimatedTokens int64 `json:"estimatedTokens"`
	Events []KnowledgeTraceEvent `json:"events"`
	Loaded []string `json:"loaded"`
	Available []string `json:"available"`
	// Cleanup must be called after the native CLI exits.
}

func knowledgeApplicable(e KnowledgeEntry,role string,languages []string)bool{
	match:=func(target string, values []string)bool {
		if len(values)==0{return true}
		for _,v:=range values{if strings.EqualFold(strings.TrimSpace(v),target){return true}}
		return false
	}
	if !match(strings.ToLower(strings.TrimSpace(role)),e.Roles){return false}
	if len(e.Languages)>0{
		for _,language:=range languages{if match(strings.ToLower(strings.TrimSpace(language)),e.Languages){return true}}
		return false
	}
	return true
}
func compactKnowledgeIndex(entries []KnowledgeEntry)string{
	var b strings.Builder
	for _,e:=range entries{
		fmt.Fprintf(&b,"- %s | %s | %s | %s\n",e.ID,e.Title,e.Kind,e.Description)
	}
	return b.String()
}

// BuildKnowledgeContext does not invoke a model or perform network retrieval.
// It copies only eligible on-demand documents into a run-scoped directory and
// injects bootstrap documents exactly once for this execution.
func BuildKnowledgeContext(req KnowledgeContextRequest)(KnowledgeContext,error){
	var out KnowledgeContext
	if strings.TrimSpace(req.Root)==""{return out,errors.New("knowledge root required")}
	pack,err:=(&KnowledgeSource{}).LoadLocal(req.Root);if err!=nil{return out,err}
	assigned:=make(map[string]bool,len(req.Assigned))
	for _,id:=range req.Assigned{assigned[id]=true}
	eligible:=make([]KnowledgeEntry,0)
	for _,e:=range pack.Entries{
		if !knowledgeApplicable(e,req.Role,req.Languages){continue}
		if e.Load=="bootstrap" || assigned[e.ID] {eligible=append(eligible,e)}
	}
	// Reject IDs absent from the source or not applicable to this role/language.
	for _,id:=range req.Assigned{
		found:=false
		for _,e:=range eligible{if e.ID==id {found=true;break}}
		if !found{return out,fmt.Errorf("knowledge assignment %q is missing or not applicable",id)}
	}
	if len(eligible)==0{return out,errors.New("no applicable knowledge documents")}
	sort.SliceStable(eligible,func(i,j int)bool{return eligible[i].ID<eligible[j].ID})
	var body strings.Builder
	var bytes int
	var onDemand []KnowledgeEntry
	for _,e:=range eligible{
		source,err:=knowledgeSafeFile(pack.Root,e.Path);if err!=nil{return out,fmt.Errorf("%s: %w",e.ID,err)}
		raw,err:=os.ReadFile(source);if err!=nil{return out,err}
		sum:=sha256.Sum256(raw)
		hash:=hex.EncodeToString(sum[:])
		if e.SHA256!="" && !strings.EqualFold(e.SHA256,hash){return out,fmt.Errorf("knowledge checksum mismatch: %s",e.ID)}
		event:=KnowledgeTraceEvent{Kind:"knowledge.selected",DocumentID:e.ID,Status:e.Status,SHA256:hash,EstimatedTokens:int64((len(raw)+3)/4)}
		if e.Load=="bootstrap"{
			// Strip metadata frontmatter from the injected body to reduce context.
			docBody:=knowledgeMarkdownBody(raw)
            bytes+=len(docBody)
			if bytes>knowledgeBootstrapLimit{return out,errors.New("knowledge bootstrap body exceeds 24 KB limit")}
			fmt.Fprintf(&body,"\n--- %s (%s) ---\n%s\n",e.Title,e.ID,string(docBody))
			out.Loaded=append(out.Loaded,e.ID)
			event.Kind="knowledge.injected"
		}else{
			onDemand=append(onDemand,e)
			out.Available=append(out.Available,e.ID)
			event.Kind="knowledge.available"
		}
		out.Events=append(out.Events,event)
	}
	out.Bootstrap=body.String()
	out.Index=compactKnowledgeIndex(onDemand)
	out.EstimatedTokens=int64((len(out.Bootstrap)+len(out.Index)+3)/4)
	// No directory is created for a bootstrap-only assignment.
	if len(onDemand)==0{return out,nil}
	dir,err:=os.MkdirTemp("","ae-knowledge-*");if err!=nil{return KnowledgeContext{},err}
	cleanup:=true
	defer func(){if cleanup{os.RemoveAll(dir)}}()
	for _,e:=range onDemand{
		source,err:=knowledgeSafeFile(pack.Root,e.Path);if err!=nil{return out,err}
		raw,err:=os.ReadFile(source);if err!=nil{return out,err}
		// Paths are validated by knowledgeSafeFile. This directory contains no unassigned documents.
		clean := filepath.Clean(e.Path)
		if filepath.IsAbs(e.Path) || clean=="." || clean==".." || strings.HasPrefix(clean, ".."+string(os.PathSeparator)) || strings.HasPrefix(clean, ".git"+string(os.PathSeparator)) {
			return KnowledgeContext{}, fmt.Errorf("unsafe on-demand document path: %s",e.ID)
		}
		target:=filepath.Join(dir,clean)
		if err:=os.MkdirAll(filepath.Dir(target),0700);err!=nil{return out,err}
		if err:=os.WriteFile(target,raw,0600);err!=nil{return out,err}
	}
	out.Directory=dir
	cleanup=false
	return out,nil
}
